const q = (query || '').toLowerCase();
const faq = [
  { keys: ['versand', 'verschick', 'shipping', 'versandkosten'], a: 'Standardversand kostet 3,99 EUR, ab 50 EUR Bestellwert ist der Versand kostenlos.' },
  { keys: ['lieferzeit', 'wie lange', 'wann kommt', 'dauer'], a: 'Die Lieferzeit betraegt in der Regel 2 bis 4 Werktage innerhalb Deutschlands.' },
  { keys: ['rueckgabe', 'rückgabe', 'retoure', 'zurueck', 'zurück', 'umtausch', 'widerruf'], a: 'Du kannst Artikel innerhalb von 30 Tagen kostenlos zurueckgeben. Das Retourenlabel findest du in deinem Kundenkonto.' },
  { keys: ['zahlung', 'bezahlen', 'zahlungsart', 'paypal', 'rechnung', 'kreditkarte', 'klarna'], a: 'Wir akzeptieren PayPal, Kreditkarte, Klarna und Kauf auf Rechnung.' },
  { keys: ['kontakt', 'erreichen', 'telefon', 'email', 'support', 'hotline'], a: 'Unser Support ist Mo bis Fr von 9 bis 17 Uhr unter support@voltbox.de erreichbar.' }
];
for (const item of faq) {
  if (item.keys.some(k => q.includes(k))) {
    return item.a;
  }
}
return 'NICHT_GEFUNDEN';
